sys_script_client.script:
function onSubmit() {

    // Only applies to Task 3 - Equipment Configuration
    var taskName = g_form.getValue('short_description');
    if (taskName.indexOf('Equipment Configuration - Configure the equipment') === -1) return true;

    // Only block if trying to close the task
    var state = g_form.getValue('state');
    if (state !== '3') return true; // 3 = Closed Complete

    // Check if work notes is filled
    var configNotes = g_form.getValue('configuration_notes');
    if (!configNotes) {
        g_form.addErrorMessage('Configuration Notes must be filled before closing this task.');
        return false; // blocks the form from saving
    }

    return true;
}
